TOPO = {"dn1": "/rack1", "dn2": "/rack2", "dn3": "/rack2", "dn4": "/rack3", "dn5": "/rack1"}
def place(block, writer="dn1", rep=3):
    chosen = []
    racks_used = set()
    order = [writer] + [d for d in TOPO if d != writer]
    for dn in order:
        if len(chosen) >= rep:
            break
        if dn in chosen:
            continue
        r = TOPO[dn]
        if len(chosen) == 0:
            chosen.append(dn); racks_used.add(r)
        elif len(chosen) == 1:
            if r != next(iter(racks_used)):   # 第2副本跨机架
                chosen.append(dn); racks_used.add(r)
        else:
            if r in racks_used:               # 第3副本与第2同机架
                chosen.append(dn)
    return chosen
res = place("blk_X")
print("placement:", res)
print("racks:", [TOPO[d] for d in res])
print("first_two_distinct_racks:", len(set(TOPO[d] for d in res[:2])))
